		PhoneHashKey:    getenv("PHONE_HASH_KEY", "dev-phone-hash-key-change-me"),
		SMSMode:         getenv("SMS_MODE", "mock"),
		SMSMockCode:     getenv("SMS_MOCK_CODE", "123456"),
	}

	if cfg.DatabaseURL == "" {
		return Config{}, errors.New("DATABASE_URL is required")
